function normalizeQueries(
	query: string | undefined,
	queries: string[] | undefined,
): string[] {
	const list = [
		...(queries && Array.isArray(queries) ? queries.filter((q) => typeof q === "string" && q.trim()) : []),
	];
	if ((!list.length) && typeof query === "string" && query.trim()) {
		list.push(query.trim());
	}
	return list.map((q) => q.trim()).filter(Boolean);
}

function buildWebSearchMessages(
	query: string,
	opts: {
		recencyFilter?: string;
		domainFilter?: string[];
		numResults?: number;
		includeContent: boolean;
	},
): PerplexityMessage[] {
	const hints: string[] = [];
	if (opts.recencyFilter) {
		hints.push(`Focus on results from the last ${opts.recencyFilter}.`);
	}
	if (opts.domainFilter && opts.domainFilter.length) {
		const include = opts.domainFilter.filter((d) => !d.startsWith("-"));
		const exclude = opts.domainFilter.filter((d) => d.startsWith("-")).map((d) => d.slice(1));
		if (include.length) hints.push(`Prefer these domains: ${include.join(", ")}.`);
		if (exclude.length) hints.push(`Avoid these domains: ${exclude.join(", ")}.`);
	}
	const systemBase = opts.includeContent
		? "You are a helpful web research assistant. Answer concisely and accurately, and cite sources."
		: "You are a web search index. Return only a concise list of the most relevant source titles and URLs, one per line, no prose.";
	const system = hints.length ? `${systemBase}\n\n${hints.join(" ")}` : systemBase;
	return [
		{ role: "system", content: system },
		{ role: "user", content: query },
	];
}

function formatWebSearchResults(
	results: Array<{ query: string; content: string; citations: PerplexitySource[] }>,
	includeContent: boolean,
): string {
	const blocks: string[] = [];
	results.forEach((r, i) => {
		const header = `## Query ${results.length > 1 ? `${i + 1}` : ""}: ${r.query}`.replace("Query : ", "Query: ");
		if (includeContent) {
			blocks.push(`${header}\n\n${r.content.trim()}\n\nSources:\n${formatSources(r.citations).replace(/^\n\nSources:\n/, "")}`);
		} else {
			blocks.push(`${header}\n${r.content.trim()}`);
		}
	});
	return blocks.join("\n\n---\n\n");
}
