	const WebSearchParams = Type.Object({
		query: Type.Optional(Type.String({ description: "Single search query. Prefer `queries` for multiple angles." })),
		queries: Type.Optional(Type.Array(Type.String(), { description: "Batch of search queries; each gets its own answer + sources." })),
		numResults: Type.Optional(Type.Number({ description: "Result-count hint (Perplexity controls citation count).", default: 5 })),
		recencyFilter: Type.Optional(StringEnum(WEB_RECENCY_VALUES, { description: "Bias toward a recency window." })),
		domainFilter: Type.Optional(Type.Array(Type.String(), { description: "Domains to include (prefix with `-` to exclude)." })),
		includeContent: Type.Optional(Type.Boolean({ description: "Return synthesized answers (true, default) or just source lists (false).", default: true })),
	});

	pi.registerTool({
		name: "web_search",
		label: "Web Search",
		description: "Search the web and return answers with numbered sources. Backed by Perplexity. Accepts `query` or a `queries` array (preferred for covering multiple angles). Use for fresh info, current events, library/API docs, or anything not in local files. This is a Perplexity-backed shim for the `web_search` tool that pi-subagents (researcher, context-builder) expect from pi-web-access.",
		promptSnippet: "Web search (Perplexity) — `queries` array supported",
		promptGuidelines: [
			"Pass 2-4 distinct angles via `queries` rather than one generic query.",
			"Cite the returned source numbers inline.",
		],
		parameters: WebSearchParams,
		async execute(_toolCallId, params, signal) {
			const queries = normalizeWebQueries(params.query, params.queries);
			if (!queries.length) {
				return { content: [{ type: "text", text: "web_search: provide a `query` or `queries`." }], details: { results: [] } };
			}
			const includeContent = params.includeContent !== false;
			const results = await Promise.all(queries.map(async (q) => {
				const messages = buildWebSearchMessages(q, {
					recencyFilter: params.recencyFilter,
					domainFilter: params.domainFilter,
					numResults: params.numResults,
					includeContent,
				});
				const result = await searchPerplexity(messages, DEFAULT_SEARCH_MODEL, { signal });
				return { query: q, ...result };
			}));
			let text = formatWebSearchResults(results, includeContent);
			const truncation = truncateHead(text, { maxBytes: DEFAULT_MAX_BYTES });
			if (truncation.truncated) text = truncation.content + `\n\n[Output truncated: ${formatSize(truncation.outputBytes)} of ${formatSize(truncation.totalBytes)}. ${truncation.outputLines}/${truncation.totalLines} lines.]`;
			return {
				content: [{ type: "text", text }],
				details: { model: DEFAULT_SEARCH_MODEL, queries, results, sources: results.flatMap((r) => r.citations) },
			};
		},
		renderCall(args, theme) {
			const queries = normalizeWebQueries(args.query as string | undefined, args.queries as string[] | undefined);
			const first = queries[0] ?? "";
			const preview = first.length > 60 ? `${first.slice(0, 60)}…` : first;
			const more = queries.length > 1 ? ` +${queries.length - 1}` : "";
			return new Text(theme.fg("toolTitle", theme.bold("web_search ")) + theme.fg("muted", `[${DEFAULT_SEARCH_MODEL}] `) + theme.fg("dim", preview + more), 0, 0);
		},
		renderResult(result, { expanded }, theme) {
			const text = result.content[0]?.type === "text" ? result.content[0].text : "(no output)";
			if (expanded) return new Markdown(text, 0, 0, getMarkdownTheme());
			const firstLine = text.split("\n")[0] ?? text;
			const sources = result.details?.sources as PerplexitySource[] | undefined;
			const srcCount = sources ? ` · ${sources.length} source${sources.length === 1 ? "" : "s"}` : "";
			return new Text(theme.fg("toolOutput", firstLine.slice(0, 200)) + theme.fg("dim", srcCount), 0, 0);
		},
	});
